from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def purge(current_time):
        expired_keys = [k for k, (v, wt) in cache.items() if current_time >= wt + ttl]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            purge(t)
            if key in cache:
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            purge(t)
            if key in cache:
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

